class Solution:
    def possiblyEquals(self, s1: str, s2: str) -> bool:
        n, m = len(s1), len(s2)

        def parses(s, p):
            out = []
            v = 0
            for k in range(p, min(len(s), p + 3)):
                if not s[k].isdigit():
                    break
                v = v * 10 + int(s[k])
                out.append((v, k + 1))
            return out

        def dfs(i, j, d):
            if i == n and j == m:
                return d == 0
            if d > 0:
                if j == m:
                    return False
                if s2[j].isalpha():
                    return dfs(i, j + 1, d - 1)
                return any(dfs(i, nj, d - v) for v, nj in parses(s2, j))
            if d < 0:
                if i == n:
                    return False
                if s1[i].isalpha():
                    return dfs(i + 1, j, d + 1)
                return any(dfs(ni, j, d + v) for v, ni in parses(s1, i))
            if i < n and j < m:
                if s1[i].isalpha() and s2[j].isalpha():
                    return s1[i] == s2[j] and dfs(i + 1, j + 1, 0)
                if s1[i].isdigit() and any(dfs(ni, j, v) for v, ni in parses(s1, i)):
                    return True
                if s2[j].isdigit() and any(dfs(i, nj, -v) for v, nj in parses(s2, j)):
                    return True
            return False

        return dfs(0, 0, 0)

