private:
    int n, m;
    string a, b;

    vector<pair<int,int>> parses(const string& s, int p) {
        vector<pair<int,int>> out;
        int v = 0;
        for (int k = p; k < (int)s.size() && k < p + 3 && isdigit((unsigned char)s[k]); ++k) {
            v = v * 10 + (s[k] - '0');
            out.push_back({v, k + 1});
        }
        return out;
    }

    bool dfs(int i, int j, int d) {
        if (i == n && j == m) return d == 0;
        bool res = false;
        if (d > 0) {
            if (j < m) {
                if (isalpha((unsigned char)b[j])) res = dfs(i, j + 1, d - 1);
                else for (auto& [v, nj] : parses(b, j)) if (dfs(i, nj, d - v)) { res = true; break; }
            }
        } else if (d < 0) {
            if (i < n) {
                if (isalpha((unsigned char)a[i])) res = dfs(i + 1, j, d + 1);
                else for (auto& [v, ni] : parses(a, i)) if (dfs(ni, j, d + v)) { res = true; break; }
            }
        } else if (i < n && j < m) {
            if (isalpha((unsigned char)a[i]) && isalpha((unsigned char)b[j])) {
                res = a[i] == b[j] && dfs(i + 1, j + 1, 0);
            } else {
                if (isdigit((unsigned char)a[i]))
                    for (auto& [v, ni] : parses(a, i)) if (dfs(ni, j, v)) { res = true; break; }
                if (!res && isdigit((unsigned char)b[j]))
                    for (auto& [v, nj] : parses(b, j)) if (dfs(i, nj, -v)) { res = true; break; }
            }
        }
        return res;
    }
};

