class Solution {
    private int n, m;
    private String a, b;

    public boolean possiblyEquals(String s1, String s2) {
        a = s1;
        b = s2;
        n = a.length();
        m = b.length();
        return dfs(0, 0, 0);
    }

    private List<int[]> parses(String s, int p) {
        List<int[]> out = new ArrayList<>();
        int v = 0;
        for (int k = p; k < s.length() && k < p + 3 && Character.isDigit(s.charAt(k)); k++) {
            v = v * 10 + (s.charAt(k) - '0');
            out.add(new int[]{v, k + 1});
        }
        return out;
    }

    private boolean dfs(int i, int j, int d) {
        if (i == n && j == m) return d == 0;
        boolean res = false;
        if (d > 0) {
            if (j < m) {
                if (Character.isLetter(b.charAt(j))) res = dfs(i, j + 1, d - 1);
                else for (int[] pr : parses(b, j)) if (dfs(i, pr[1], d - pr[0])) { res = true; break; }
            }
        } else if (d < 0) {
            if (i < n) {
                if (Character.isLetter(a.charAt(i))) res = dfs(i + 1, j, d + 1);
                else for (int[] pr : parses(a, i)) if (dfs(pr[1], j, d + pr[0])) { res = true; break; }
            }
        } else if (i < n && j < m) {
            char c1 = a.charAt(i), c2 = b.charAt(j);
            if (Character.isLetter(c1) && Character.isLetter(c2)) {
                res = c1 == c2 && dfs(i + 1, j + 1, 0);
            } else {
                if (Character.isDigit(c1))
                    for (int[] pr : parses(a, i)) if (dfs(pr[1], j, pr[0])) { res = true; break; }
                if (!res && Character.isDigit(c2))
                    for (int[] pr : parses(b, j)) if (dfs(i, pr[1], -pr[0])) { res = true; break; }
            }
        }
        return res;
    }
}

